<script>
import appConfig from "@/app.config";
export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {},
  data() {
    return {
      masterPayroll: [],
      selectedPaymentMethod: {},
      deductions: [],
      paymentMethods: [],
      addAsset: [{}],
      currentAssets: [],
      employeeDeduction: {},
      salaryItems: [],
      data: {},
      totalSalary: 0,
      paymentMethod: {},
      totalDeductions: 0,
      salaries_total: [],
      total_dedu: {},
      submittedPayments: {},
    };
  },
  computed: {
    computedTotalSalary() {
      let totalItems = 0;
      let totalDeductionsInput = 0;

      this.masterPayroll.forEach(emp => {
        const penalty = parseFloat(emp.penalty || 0);
        const employeeDeduction = parseFloat(emp.employeeDeduction || 0);
          
        totalDeductionsInput += employeeDeduction + penalty;
        totalItems += parseFloat(emp?.total_balance || 0);
      });

      return totalItems - totalDeductionsInput;
    }
  },
  methods: {
    getPaymentMethods() {
      this.http.post("transactions/cash-accounts", {}).then((res) => {
        this.paymentMethods = res.data;
        console.log('toooooota', res)
      });
    },
    changePaymentMethod() {
      this.paymentMethods.forEach((method) => {
        if (method.cash_account_id == this.data.cash_account_id) {
          this.selectedPaymentMethod = method;
        }
      });
    },
    getSalaryItemBranches() {
      this.http
        .post("salary-items-branches/branch-items-query", {})
        .then((res) => {
          if (res.status) {
            this.salaryItems = res.data;
            console.log('sssss', this.salaryItems)
          }
        });
    },
    getMasterPayroll() {
      this.data.month = parseInt(this.data.date.split("-")[1]);
      this.data.year = this.data.date.split("-")[0];
      this.http.post("transactions/master-payroll", this.data).then((res) => {
        if (res.status) {
          this.masterPayroll = res.data;
          this.salaries_total = res.salaries
          this.total_dedu = res.totals
          console.log('asdfsdfsdfs', res.data);
          if (this.masterPayroll?.length > 0) {
            document.querySelectorAll(".money-btn").forEach((element) => {
              element.removeAttribute("disabled");
            });
          }
          if(res.msg) {
             this.popup.alert({
          title: this.$t("payroll.master.notification"),
          msg: this.$t("payroll.master.already_generated_msg")
        });
          }
        }
      });
    },
    changeDeduction(event, item) {
      console.log(item);
      if (event.target.value <= 0) {
        item.employeeDeduction = 0;
        return;
      }
      if (parseFloat(event.target.value) > parseFloat(item.total_loan)) {
        var data = {
          title: "popups.warning",
          template: `
          <h5>the deduction you insert it is more than the total  ?</h5>
        `,
        };
        this.popup.modal(data);
        item.employeeDeduction = 0;
        return;
      }
      // item.total_paid =
      //   parseFloat(item.total_paid) + parseFloat(event.target.value);
      item.employeeDeduction = parseFloat(event.target.value);
      // this.http
      //   .put("emps/loans", item.id, {
      //     paid_balance: parseFloat(event.target.value),
      //     month: this.data.month,
      //     year: this.data.year,
      //     emp_id: item.id,
      //   })
      //   .then((res) => {
      //     if (!res.status) {
      //       var data = {
      //         title: "popups.error",
      //         template: `
      //     <h5>try again later  ?</h5>
      //   `,
      //       };
      //       this.popup.modal(data);
      //       event.target.value = 0;
      //       return;
      //     }
      //     console.log("done");
      //   });
    },
    payMasterPayrollSalaries() {
       const key = `${this.data.year}-${String(this.data.month).padStart(2, '0')}`;
      const emps = this.masterPayroll.map((emp) => {
        return {
          id: emp.id,
          deduction: emp.employeeDeduction ? emp.employeeDeduction : 0,
          total_balance: emp.total_balance,
        };
      });
      console.log(emps);
      this.http
        .post("transactions/emps/pay", {
          month: this.data.month,
          year: this.data.year,
          emps,
          totalSalaries: this.totalSalary,
          totalDeductions: this.totalDeductions,
          cash_account_id: this.data.cash_account_id,
        })
        .then((res) => {
          if (res.status) {
            this.submittedPayments[key] = true;
            document.querySelectorAll(".money-btn").forEach((element) => {
              element.setAttribute("disabled", true);
            });
            console.log("done");
          }
        });
    },
    processPayModalData() {
      console.log('begin with this',this.masterPayroll);
      let totalItems = 0,
        totalDeductionsInput = 0;
      this.masterPayroll.forEach((emp) => {
        if (emp.employeeDeduction) {
          totalDeductionsInput += parseFloat(emp.employeeDeduction);
        }
        totalItems += parseFloat(emp?.total_balance);
      });

      console.log('llllldldldldldldl', { totalItems });
      this.totalDeductions = parseFloat(totalDeductionsInput);
      this.totalSalary =
        parseFloat(totalItems) - parseFloat(totalDeductionsInput);
      this.paymentMethod = this.selectedPaymentMethod;
    },
    getDeductions() {
      this.http.get("salary-deduction").then((res) => {
        this.deductions = res.data;
      });
    },
  },
  created() {
    this.getPaymentMethods();
    this.getSalaryItemBranches();
    // this.getDeductions();
  },
};
</script>

