  <div class="row mb-4">
    <div class="col-md-10">
      <form @submit.prevent="getMasterPayroll()">
        <div class="row" style="align-items: flex-end">
          <div class="col">
            <label class="inline" for="toJobTitle">{{
              $t("payroll.master.date")
            }}</label>
            <input type="month" class="form-control" v-model="data.date" />
          </div>
          <div class="col">
            <label class="inline" for="toJobTitle">{{
              $t("payroll.master.payment_method")
            }}</label>
            <select
              v-model="data.cash_account_id"
              class="form-control fromto"
              id="toJobTitle"
              @change="changePaymentMethod()"
            >
              <option
                v-for="payment in paymentMethods"
                :key="payment"
                :value="payment.cash_account_id"
                :selcted="paymentMethods[-1]"
              >
                {{ $i18n.locale == "ar" ? payment?.name : payment?.name_en }}
              </option>
            </select>
          </div>
          <div class="col">
            <button type="submit" class="btn btn-primary">
              {{ $t("popups.search") }}
            </button>
          </div>
        </div>
      </form>
    </div>
    <div class="col-md-2 align-self-end">
      <button
        type="submit"
        class="btn btn-primary money-btn"
        data-bs-toggle="modal"
        @click="processPayModalData()"
        data-bs-target="#payPayrollModal"
        v-if="masterPayroll?.length > 0"
      >
        {{ $t("payroll.pay") }}
      </button>
    </div>
  </div>

  <div class="row">
    <div class="col-12">
      <div class="card">
        <div class="card-body">
          <div class="table-responsive">
            <table
              v-if="masterPayroll.length > 0"
              :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'"
              class="table table-centered table-nowrap align-middle"
              style="border: 2px solid gray"
            >
              <thead>
                <tr class="text-center" style="border: 2px solid gray">
                  <th style="border: 2px solid gray" scope="col" colspan="2">
                    {{ $t("payroll.master.descr") }}
                  </th>
                  <th
                    style="border: 2px solid gray"
                    scope="col"
                    :colspan="salaryItems.length"
                  >
                    {{ $t("payroll.master.earnings") }}
                  </th>
                  <th></th>
                  <th style="border: 2px solid gray" scope="col"></th>
                  <th style="border: 2px solid gray" scope="col" colspan="6">
                    {{ $t("payroll.master.deductions") }}
                  </th>
                  <th
                    style="border: 2px solid gray"
                    scope="col"
                    rowspan="2"
                  ></th>
                </tr>
              </thead>
              <tbody>
                <tr style="border: 2px solid gray">
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.no") }}
                  </th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.name_of_emp") }}
                  </th>
                  <th
                    style="border: 2px solid gray"
                    v-for="item in salaryItems"
                    :key="item"
                  >
                    {{ $i18n.locale == "ar" ? item?.name : item?.name_en }}
                  </th>
                  <th style="border: 2px solid gray">{{ $t('payroll.master.overtime') }}</th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.gross") }}
                  </th>
                  <th
                    style="border: 2px solid gray"
                    v-for="deduction in deductions"
                    :key="deduction"
                  >
                    {{
                      $i18n.locale == "ar"
                        ? deduction?.name
                        : deduction?.name_en
                    }}
                  </th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.tax") }}
                  </th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.penalties") }}
                  </th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.insurance") }}
                  </th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.total_loan") }}
                  </th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.normal_leave") }}
                  </th>
                  
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.absence_deduction") }}
                  </th>
                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.deductabe_loan") }}
                  </th>

                  <th style="border: 2px solid gray">
                    {{ $t("payroll.master.net") }}
                  </th>
                </tr>
                <tr
                  style="border: 2px solid gray"
                  v-for="(item, index) in masterPayroll"
                  :key="item"
                >
                  <td style="border: 2px solid gray">{{ index + 1 }}</td>
                  <td style="border: 2px solid gray">{{ item?.name }}</td>
                  <td
                    style="border: 2px solid gray"
                    v-for="(salary, i) in salaryItems"
                    :key="i"
                  >
                    {{
                      (
                        item.salary_items.find(
                          s => s.salary_item_id === salary.id
                        )?.value ?? 0
                      ).toLocaleString()
                    }}
                  </td>
                  <td>
                    {{ parseFloat(item.overtime_value) || 0 }}
                  </td>
                  <td style="border: 2px solid gray">
                    {{
                      item.salary_items
                        .reduce(
                          (accumulator, salaryItem) =>
                            accumulator +
                            parseFloat(
                              salaryItem?.value ? salaryItem?.value : 0
                            ),
                          0
                        )
                        ?.toLocaleString()
                    }}
                  </td>
                  <td style="border: 2px solid gray">{{ parseFloat(item?.tax) }}</td>
                  <td style="border: 2px solid gray">{{ parseFloat(item?.penalty) || 0 }}</td>
                  <td style="border: 2px solid gray">
                    {{
                      (
                        item.salary_items.reduce(
    (acc, salaryItem) =>
      acc +
      (
        (salaryItem.name_en.toLowerCase() === "cost of living" || salaryItem.name_en.toLowerCase() === "basic salary")
          ? parseFloat(salaryItem?.value || 0) : 0
      ),
    0
  ) * item?.insurance
).toLocaleString()
                    }}
                  </td>
                  <td style="border: 2px solid gray">
                    {{ parseFloat(item?.total_loan).toLocaleString() }}
                  </td>
                  <td style="border: 2px solid gray">
                    {{ parseFloat(item?.normal_leave_deduction).toLocaleString() || 0 }}
                  </td>
                  <td style="border: 2px solid gray">
                    {{ parseFloat(item?.absence_deduction).toLocaleString()|| 0 }}
                  </td>
                  <td style="border: 2px solid gray">
                    <input
                      class="money-btn"
                      @change="changeDeduction($event, item)"
                      type="number"
                      :value="
                        item.employeeDeduction ? item.employeeDeduction : 0
                      "
                    />
                  </td>
                  <td style="border: 2px solid gray">
                    {{
                      (
                        item.salary_items.reduce(
                          (accumulator, salaryItem) =>
                            accumulator +
                            parseFloat(
                              salaryItem?.value ? salaryItem?.value : 0
                            ),
                          0
                        ) -
                        item.salary_items.reduce(
    (acc, salaryItem) =>
      acc +
      (
        (salaryItem.name_en.toLowerCase() === "cost of living" || salaryItem.name_en.toLowerCase() === "basic salary")
          ? parseFloat(salaryItem?.value || 0) : 0
      ),
    0
  ) * item?.insurance -
      parseFloat(item?.tax) - parseFloat(item?.total_loan) - parseFloat(item?.absence_deduction) - 
      parseFloat(item?.normal_leave_deduction || 0) + parseFloat(item.overtime_value) - 
      parseFloat(item?.penalty || 0) - parseFloat(item?.employeeDeduction ? item?.employeeDeduction : 0) 
                      )?.toLocaleString()
                    }}
                  </td>
                </tr>
                <tr>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">#</td>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ $t('payroll.master.total') }}</td>

  <td
    v-for="(salary, i) in salaries_total"
    :key="i"
    style="border: 2px solid gray; font-size: larger; font-weight: bold;"
  >
    {{ salary.total_salary}}
  </td>

  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ parseFloat(total_dedu.overtime_value).toLocaleString() }}</td>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ salaries_total.reduce((sum, item) => sum + parseFloat(item.total_salary || 0), 0).toLocaleString() }}</td>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ parseFloat(total_dedu.tax).toLocaleString() }}</td>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ parseFloat(total_dedu.penalty).toLocaleString() }}</td>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">
  {{
    masterPayroll.reduce((totalInsurance, emp) => {
      const base = emp.salary_items?.reduce((sum, item) => {
        return ["basic salary", "cost of living"].includes(item.name_en?.toLowerCase())
          ? sum + parseFloat(item.value || 0)
          : sum;
      }, 0);
      return totalInsurance + base * parseFloat(emp.insurance || 0);
    }, 0).toLocaleString()
  }}
</td>



  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ parseFloat(total_dedu.total_loan).toLocaleString() }}</td>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ parseFloat(total_dedu.normal_leave_deduction).toLocaleString() }}</td>
  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">{{ parseFloat(total_dedu.absence_deduction).toLocaleString() }}</td>
  <td style="border: 2px solid gray; font-weight: bold;">{{$t('payroll.master.totalnewpay')}}</td>

  <td style="border: 2px solid gray; font-size: larger; font-weight: bold;">
    {{ computedTotalSalary.toLocaleString() }}
  </td>
</tr>

              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!--Start Add Modal-->
  <div
    class="modal fade"
    id="payPayrollModal"
    tabindex="-1"
    aria-labelledby="exampleModalLabel"
    aria-hidden="true"
    :dir="$i18n.locale == 'ar' ? 'rtl' : ''"
  >
    <div class="modal-dialog">
      <div class="modal-content">
        <form @submit.prevent="payMasterPayrollSalaries()">
          <div class="modal-header">
            <div class="d-flex justify-content-around">
              <!-- <h5 class="modal-title" id="exampleModalLabel">
                {{ $t("emps.pay") }}
              </h5> -->
              <h5 class="modal-title" id="exampleModalLabel">
