            ></button>
          </div>

          <div class="modal-body">
            <div class="pay-card">
              <div class="mb-4">
                <label for="asset_id">{{
                  $t("emps.payment_details.title")
                }}</label>
                <hr />
              </div>
              <div class="row">
                <div class="col">
                  <label class="d-block">
                    {{ $t("emps.payment_details.from") }}
                  </label>
                  <hr />
                  <label class="d-block">
                    {{ $t("emps.payment_details.amount") }}
                  </label>
                  <hr />

                  <label class="d-block">
                    {{ $t("emps.payment_details.month") }}
                  </label>
                  <hr />

                  <label class="d-block">
                    {{ $t("emps.payment_details.year") }}
                  </label>
                  <hr />
                </div>
                <div class="col">
                  <label class="d-block">
                    {{
                      $i18n.locale == "ar"
                        ? paymentMethod?.name
                        : paymentMethod?.name_en
                    }}
                  </label>
                  <hr />

                  <label class="d-block">
                    {{ parseFloat(totalSalary).toLocaleString() }}
                  </label>
                  <hr />

                  <label class="d-block">
                    {{ data.month }}
                  </label>
                  <hr />

